import {ITEMS,RECIPES} from './engine.js?v=0.20.1';
import {projectPlan} from './project-planning.js?v=0.20.1';
export function projectPanelView(s,goal,{costs,resourceIcon}){
 const p=projectPlan(s,goal);
 if(!p.valid)return '<h2>This project has moved on.</h2><p class="description">Open its current stage to plan the next delivery.</p><button class="button secondary" data-tab="build">View town projects</button>';
 return `<div class="panel-eyebrow">PRODUCTION PLAN</div><h2>${p.title}</h2><p class="description">Stored goods and queued production count toward this plan. Other orders’ reservations remain protected.</p><div class="project-requirements">${p.requirements.map(r=>`<article><strong>${resourceIcon(r.item)}${ITEMS[r.item]||'Coins'}</strong><span>${r.available} available · ${r.incoming} queued / ${r.required} needed</span><b>${r.missing?r.missing+' still needed':'Covered'}</b>${r.missing?`<button class="text-button" data-action="ingredient" data-key="${r.item}" data-goal="${goal}">Find source →</button>`:''}</article>`).join('')}</div>${p.ready?'<p class="success-tag">Supplies ready. Return to the project to deliver them.</p>':`<button class="button" data-action="queue-project" data-goal="${goal}" ${p.queueable?'':'disabled'}>Queue missing batches${p.queueable?' · '+p.queueable:''}</button><p class="hint">Starts only work with available ingredients and queue space now. It does not enable automatic production. Return after batches finish to queue the next steps.</p>`}${p.blockers.length?`<section class="project-blockers"><h3>What needs attention</h3>${p.blockers.map(b=>`<p>${b.message}</p>`).join('')}</section>`:''}${p.bottlenecks.length?`<section class="project-workload"><h3>Workshop workload</h3><p class="hint">New production time required. Workshops run in parallel; this is not an estimated finishing time.</p>${p.bottlenecks.map((b,i)=>`<div><strong>${b.station}${i===0?' · most work':''}</strong><span>${b.batches} batches · ${Math.ceil(b.seconds)} simulation seconds</span></div>`).join('')}</section>`:''}${p.recipes.length?`<h3>Production steps</h3>${p.recipes.map(r=>`<article class="project-step"><strong>${RECIPES[r.key].name}</strong><p>${r.batches} batches · ${costs(RECIPES[r.key].cost)||'No ingredients'} per batch → ${costs(RECIPES[r.key].output)}</p><button class="text-button" data-station="${r.station}">Open workshop →</button></article>`).join('')}`:''}<button class="button secondary" data-action="open-goal" data-goal="${goal}">Return to project →</button>`;
}
